#include "fibre_arithmetic.hpp"
#include "rank_roots.hpp"

struct SPoint{F x,y;Point image;int index=-1,sign=0;};
struct Section{int origin=0;std::array<F,3> line;Poly restriction;std::array<int,4> support;SCRow row;};
std::string sp_key(const F&x,const F&y){return decimal(x)+":"+decimal(y);}
Poly ss_restrict(const BP&c,const F&x,const F&y,const F&dx,const F&dy){
 std::array<Poly,5> xx,yy;xx[0]=Poly{F(1)};yy[0]=Poly{F(1)};for(size_t i=1;i<5;++i){xx[i]=xx[i-1]*Poly{x,dx};yy[i]=yy[i-1]*Poly{y,dy};}Poly out;for(const auto&[e,a]:c.t)out=out+(xx[size_t(e[0])]*yy[size_t(e[1])]).scale(a);return out;
}
F ss_eval(const Poly&p,const F&t){F r;for(int i=p.degree();i>=0;--i)r=r*t+p.at(i);return r;}
std::vector<F> ss_quadratic(const Poly&p){
 require(p.degree()==2,"complete residual quadratic");F disc=p.at(1)*p.at(1)-F(4)*p.at(0)*p.at(2),root;BN e(BN_dup(prime()),BN_free);require(bool(e)&&BN_add_word(e.get(),1)==1&&BN_rshift(e.get(),e.get(),2)==1,"fixed square-root exponent");require(BN_mod_exp(root.n.get(),disc.n.get(),e.get(),prime(),context())==1,"quadratic square root");if(root*root!=disc)return {};F inv=(F(2)*p.at(2)).inverse();std::vector<F> r{(-p.at(1)+root)*inv,(-p.at(1)-root)*inv};require((Poly{-r[0],F(1)}*Poly{-r[1],F(1)}).scale(p.at(2))==p,"complete residual factor product");return r;
}
void ss_private(const Json&baseline,const Json&tangents){
 const auto&j=tangents.at("matrix").arr;require(j.size()==108&&tangents.at("original_base_width").integer()==225,"original tangent dimensions");auto old=sc_read_matrix(tangents.at("matrix"));require(old[0].size()==429,"original tangent width");std::vector<int> owners(108);for(size_t col=225;col<429;++col){int owner=-1;for(size_t i=0;i<108;++i)if(sc_reduce(old[i][col])!=0){require(owner<0,"original auxiliary must remain private");owner=int(i);}require(owner>=6,"original auxiliary owner");++owners[size_t(owner)];}for(size_t i=6;i<108;++i)require(owners[i]==2,"all original tangent rows have private witnesses");
 SCMat expected(6,SCRow(225));require(baseline.at("rows").arr.size()==6,"six original sparse rows");for(size_t i=0;i<6;++i){for(const auto&t:baseline.at("rows").arr[i].arr)expected[i].at(size_t(t.arr.at(0).integer()))+=SCBig(t.arr.at(1).scalar);for(size_t k=0;k<225;++k)require(sc_reduce(expected[i][k])==sc_reduce(old[i][k]),"original baseline coefficient binding");for(size_t k=225;k<429;++k)require(sc_reduce(old[i][k])==0,"original baseline has no auxiliary");}require(sc_rank(expected)==6,"recomputed original rank");
}
int main(int argc,char**argv){try{
 require(argc==8,"usage: sections QUARTIC BACKMAP BASELINE TANGENTS old|FIBRES START COUNT");int first=std::stoi(argv[6]),count=std::stoi(argv[7]);require(first>=0&&count>0&&count<=64,"fixed section batch size");auto model=read_json(argv[1]),back=read_json(argv[2]),baseline=read_json(argv[3]),tangents=read_json(argv[4]);ss_private(baseline,tangents);
 auto c=read_bp(model.at("terms"),true);std::array<BP,4> map;size_t k=0;for(const auto*key:{"X_numerator","X_denominator","Y_numerator","Y_denominator"})map[k++]=read_bp(back.at(key));require(global_identity(c,map),"actual map identity");std::vector<F> ic(5);for(const auto&[e,a]:c.t)if(e[0]+e[1]==4)ic[size_t(e[1])]=a;Poly inf(std::move(ic)),z{F(0),F(1)};require(gcd(inf,wide_power(z,prime(),inf)-z).degree()==0,"no rational infinity support omitted");
 std::vector<Point> base;std::map<std::string,int> columns;for(const auto&q:baseline.at("projected_base").arr){auto p=point(q);require(!p.zero,"nonzero old base");require(columns.emplace(decimal(p.x.p.at(0)),int(base.size())).second,"unique old signed x-column");require(BN_cmp(p.y.p.at(0).n.get(),(-p.y.p.at(0)).n.get())<=0,"canonical old sign");base.push_back(p);}require(base.size()==225,"unchanged old columns");
 std::vector<SPoint> points;std::map<std::string,int> index;
 auto intern=[&](const F&x,const F&y,const Point&claimed){auto key=sp_key(x,y);auto found=index.find(key);if(found!=index.end()){require(points[size_t(found->second)].image==claimed,"duplicate image agrees");return found->second;}auto f=fs_image(c,map,x,y);require(f.value==claimed,"fresh fibre image matches supplied coordinates");int col=-1,sign=0;if(!f.value.zero){auto hit=columns.find(decimal(f.value.x.p.at(0)));require(hit!=columns.end(),"no new elliptic unknown admitted");col=hit->second;if(f.value.y==base[size_t(col)].y)sign=1;else{require(f.value.y==-base[size_t(col)].y,"exact signed old image");sign=-1;}}int id=int(points.size());require(id<3000,"lifted point cap");index.emplace(key,id);points.push_back({x,y,f.value,col,sign});return id;};
 const auto&old=baseline.at("pool").at("points").arr;require(old.size()==226&&baseline.at("images").arr.size()==226,"original pool length");for(size_t i=0;i<old.size();++i){int id=intern(coefficient(old[i].at("x")),coefficient(old[i].at("y")),point(baseline.at("images").arr[i].at("point")));require(id==int(i),"original ordering retained");require(points[i].index==baseline.at("images").arr[i].at("projected_index").integer()&&points[i].sign==baseline.at("images").arr[i].at("sign").integer(),"original projection binding");}
 bool original=std::string(argv[5])=="old";if(original&&first==0){auto bad=baseline;auto&value=bad.obj["rows"].arr[0].arr[0].arr[1].scalar;value=SCBig(SCBig(value)+1).get_str();fs_reject([&]{ss_private(bad,tangents);});bad=tangents;bad.obj["matrix"].arr[0].arr[225].scalar="1";fs_reject([&]{ss_private(baseline,bad);});}if(!original){auto lift=read_json(argv[5]);std::set<int> targets;int start=0;for(const auto&batch:lift.at("batches").arr){require(batch.at("start").integer()==start,"ordered complete fibre batches");start+=batch.at("count").integer();for(const auto&f:batch.at("fibres").arr){int target=f.at("target").integer();require(target>=-1&&target<225&&targets.insert(target).second,"unique fibre coverage");for(const auto&p:f.at("points").arr){int id=intern(coefficient(p.at("x")),coefficient(p.at("y")),point(p.at("image")));require(points[size_t(id)].index==target,"exact target old-column identity");}}}require(start==225&&targets.size()==226&&targets.count(-1),"all old fibres covered");}
 require(size_t(first)<points.size(),"section start in pool");int last=std::min(first+count,int(points.size()));const auto&reference=baseline.at("pool").at("split_fibers").arr[0].at("point_indices").arr;require(reference.size()==4,"unchanged reference degree");Point reference_sum;for(const auto&i:reference)reference_sum=add(reference_sum,points.at(size_t(i.integer())).image);
 std::set<std::array<int,4>> seen;std::vector<Section> sections;size_t attempted=0,split=0,supported=0;
 auto accept=[&](int origin,const F&dx,const F&dy,const Poly&restriction,std::array<int,4> ids){std::sort(ids.begin(),ids.end());++supported;if(!seen.insert(ids).second)return;require(sections.size()<4096,"accepted section cap");Point sum;SCRow row(225);for(int id:ids){const auto&p=points.at(size_t(id));sum=add(sum,p.image);if(p.index>=0)row[size_t(p.index)]+=p.sign;}for(const auto&i:reference){const auto&p=points.at(size_t(i.integer()));if(p.index>=0)row[size_t(p.index)]-=p.sign;}Point negative=reference_sum;if(!negative.zero)negative.y=-negative.y;require(add(sum,negative).zero,"actual old-only elliptic row");require(!add(add(sum,negative),base[0]).zero,"changed row coefficient control");F aa=-dy,bb=dx,cc=dy*points[size_t(origin)].x-dx*points[size_t(origin)].y;sections.push_back({origin,{aa,bb,cc},restriction,ids,row});};
 for(int i=first;i<last;++i){const auto&p=points[size_t(i)];for(size_t j=size_t(i)+1;j<points.size();++j){++attempted;F dx=points[j].x-p.x,dy=points[j].y-p.y;auto q=ss_restrict(c,p.x,p.y,dx,dy);require(q.degree()==4&&q.at(0)==F(0)&&ss_eval(q,F(1))==F(0),"complete secant intersection");auto residual=q.exact(Poly{F(0),F(-1),F(1)});auto roots=ss_quadratic(residual);if(roots.empty())continue;++split;std::array<int,4> ids{i,int(j),0,0};bool all=true;for(size_t h=0;h<2;++h){auto hit=index.find(sp_key(p.x+dx*roots[h],p.y+dy*roots[h]));if(hit==index.end()){all=false;break;}ids[h+2]=hit->second;}if(all)accept(i,dx,dy,q,ids);}
 F fx=fs_eval(c.partial(0),p.x,p.y),fy=fs_eval(c.partial(1),p.x,p.y);require(fx!=F(0)||fy!=F(0),"smooth tangent");auto q=ss_restrict(c,p.x,p.y,fy,-fx);require(q.degree()==4&&q.at(0)==F(0)&&q.at(1)==F(0),"complete tangent intersection");auto roots=ss_quadratic(q.exact(Poly{F(0),F(0),F(1)}));++attempted;if(!roots.empty()){++split;std::array<int,4> ids{i,i,0,0};bool all=true;for(size_t h=0;h<2;++h){auto hit=index.find(sp_key(p.x+fy*roots[h],p.y-fx*roots[h]));if(hit==index.end()){all=false;break;}ids[h+2]=hit->second;}if(all)accept(i,fy,-fx,q,ids);}std::cerr<<"completed anchor "<<i<<'\n';}
 SCMat matrix(6,SCRow(225));for(size_t i=0;i<6;++i)for(const auto&t:baseline.at("rows").arr[i].arr)matrix[i].at(size_t(t.arr[0].integer()))+=SCBig(t.arr[1].scalar);for(const auto&s:sections)matrix.push_back(s.row);size_t rank=sc_rank(matrix);require(rank>=6,"baseline retained");
 std::cout<<"{\"scope\":\"fixed-old-column-line-sections\",\"old_mode\":"<<(original?"true":"false")<<",\"pool_size\":"<<points.size()<<",\"start\":"<<first<<",\"end\":"<<last<<",\"old_base_width\":225,\"baseline_rank\":6,\"original_auxiliary_columns\":204,\"original_auxiliary_rank\":102,\"original_private_rows\":102,\"lines_attempted\":"<<attempted<<",\"rational_residuals\":"<<split<<",\"supported_occurrences\":"<<supported<<",\"batch_candidate_closed_rank\":"<<rank<<",\"points\":[";
 for(size_t i=0;i<points.size();++i){if(i)std::cout<<',';const auto&p=points[i];std::cout<<"{\"x\":\""<<decimal(p.x)<<"\",\"y\":\""<<decimal(p.y)<<"\",\"image\":";emit(p.image);std::cout<<",\"index\":"<<p.index<<",\"sign\":"<<p.sign<<'}';}std::cout<<"],\"sections\":[";for(size_t i=0;i<sections.size();++i){if(i)std::cout<<',';const auto&s=sections[i];std::cout<<"{\"origin\":"<<s.origin<<",\"line\":[";for(size_t h=0;h<3;++h)std::cout<<(h?",":"")<<'"'<<decimal(s.line[h])<<'"';std::cout<<"],\"restriction\":";emit(s.restriction);std::cout<<",\"support\":[";for(size_t h=0;h<4;++h)std::cout<<(h?",":"")<<s.support[h];std::cout<<"],\"row\":";sc_emit_row(std::cout,s.row);std::cout<<'}';}std::cout<<"],\"positive_gain_established\":false,\"standing\":\"producer-unverified; positive candidates require separate KM/elliptic/rank checking\"}\n";
}catch(const std::exception&e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
